<script setup>
import { onMounted, reactive, ref } from 'vue'
import { ElMessage } from 'element-plus'
import { getMailConfig, updateMailConfig, testMailConnection, sendMailTest, getMailPreview, listMailDeliveries, retryMailDelivery } from '@/api/mail'
const form=reactive({version:0,enabled:false,host:'',port:587,securityMode:'STARTTLS',username:'',password:'',fromAddress:'',fromName:'',replyTo:'',connectionTimeoutMs:5000,readTimeoutMs:10000})
const delivery=reactive({recipient:'',templateKey:'VERIFICATION_CODE'}), filters=reactive({recipient:'',templateKey:'',status:'',eventId:''}), rows=ref([]), previewHtml=ref(''), saving=ref(false), testing=ref(false), sending=ref(false), loading=ref(false)
async function load(){const data=await getMailConfig();Object.assign(form,data,{password:''});await loadRows()}
async function save(){saving.value=true;try{await updateMailConfig({...form});ElMessage.success('邮件配置已保存');await load()}catch(error){if(error?.response?.status===409){ElMessage.error('配置已被其他管理员更新');await load()}}finally{saving.value=false}}
async function connection(){testing.value=true;try{await testMailConnection();ElMessage.success('连接验证成功')}finally{testing.value=false}}
async function send(){sending.value=true;try{await sendMailTest({...delivery});ElMessage.success('测试邮件已加入投递队列');await loadRows()}finally{sending.value=false}}
async function preview(){previewHtml.value=await getMailPreview(delivery.templateKey)}
async function loadRows(){loading.value=true;try{const data=await listMailDeliveries({page:1,size:50,...filters});rows.value=data?.list||[]}finally{loading.value=false}}
async function retry(row){await retryMailDelivery(row.id);ElMessage.success('已重新加入投递队列');await loadRows()}
onMounted(async()=>{await load();await preview()})
</script>
<template><main class="page"><header><small>MAIL CENTER</small><h1>邮件设置</h1></header><section class="workspace"><h2>SMTP 配置</h2><el-form label-position="top"><div class="form-grid"><el-form-item label="启用"><el-switch v-model="form.enabled"/></el-form-item><el-form-item label="主机"><el-input v-model="form.host"/></el-form-item><el-form-item label="端口"><el-input-number v-model="form.port" :min="1" :max="65535"/></el-form-item><el-form-item label="安全模式"><el-select v-model="form.securityMode"><el-option label="无" value="NONE"/><el-option label="STARTTLS" value="STARTTLS"/><el-option label="SSL/TLS" value="SSL_TLS"/></el-select></el-form-item><el-form-item label="用户名"><el-input v-model="form.username"/></el-form-item><el-form-item label="密码"><el-input v-model="form.password" type="password" autocomplete="new-password"/></el-form-item><el-form-item label="发件地址"><el-input v-model="form.fromAddress"/></el-form-item><el-form-item label="发件名称"><el-input v-model="form.fromName"/></el-form-item><el-form-item label="回复地址"><el-input v-model="form.replyTo"/></el-form-item><el-form-item label="连接超时 (ms)"><el-input-number v-model="form.connectionTimeoutMs" :min="1000" :max="60000"/></el-form-item><el-form-item label="读取超时 (ms)"><el-input-number v-model="form.readTimeoutMs" :min="1000" :max="60000"/></el-form-item></div><el-button type="primary" :loading="saving" @click="save">保存配置</el-button></el-form></section><section class="workspace"><h2>连接与测试</h2><div class="actions"><el-button :loading="testing" @click="connection">测试连接</el-button><el-input v-model="delivery.recipient" placeholder="测试收件人"/><el-select v-model="delivery.templateKey"><el-option label="验证码" value="VERIFICATION_CODE"/><el-option label="订单创建" value="ORDER_CREATED"/></el-select><el-button type="primary" :loading="sending" @click="send">发送测试邮件</el-button></div></section><section class="workspace"><h2>预览与投递记录</h2><div class="actions"><el-input v-model="filters.recipient" placeholder="收件人"/><el-input v-model="filters.eventId" placeholder="事件 ID"/><el-select v-model="filters.templateKey" clearable placeholder="模板"><el-option label="验证码" value="VERIFICATION_CODE"/><el-option label="订单创建" value="ORDER_CREATED"/></el-select><el-select v-model="filters.status" clearable placeholder="状态"><el-option label="待发送" value="PENDING"/><el-option label="重试中" value="RETRY"/><el-option label="失败" value="DEAD"/></el-select><el-button @click="preview">刷新预览</el-button><el-button @click="loadRows">查询记录</el-button></div><iframe class="mail-preview" title="邮件模板预览" sandbox="" :srcdoc="previewHtml"/><el-table v-loading="loading" :data="rows"><el-table-column prop="createdAt" label="时间" width="180"/><el-table-column prop="recipient" label="收件人"/><el-table-column prop="templateKey" label="模板" width="160"/><el-table-column prop="status" label="状态" width="110"/><el-table-column prop="attempts" label="尝试" width="80"/><el-table-column prop="lastError" label="错误"/><el-table-column label="操作" width="100"><template #default="scope"><el-button v-if="scope.row.status==='DEAD'" size="small" @click="retry(scope.row)">重试</el-button></template></el-table-column></el-table></section></main></template>
<style scoped>.page{display:grid;gap:18px}.workspace{padding:16px;border:3px solid var(--c-wood-dark);background:var(--c-surface);box-shadow:var(--shadow-pixel)}h1{font-family:var(--font-pixel);color:var(--c-wood-dark)}h2{font-size:18px}.form-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:8px}.actions{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:14px}.actions .el-input,.actions .el-select{max-width:260px}.mail-preview{display:block;width:100%;aspect-ratio:3/4;border:3px solid var(--c-wood-dark);margin-bottom:14px;background:white}</style>
